public class InnerComputeEnvironmentManagedInstancesProviderFactory(Action<Humidifier.Batch.ComputeEnvironmentTypes.ManagedInstancesProvider> factoryAction = null) : SubResourceFactory<Humidifier.Batch.ComputeEnvironmentTypes.ManagedInstancesProvider>
{

    internal InnerComputeEnvironmentInfrastructureOptimizationFactory InfrastructureOptimizationFactory { get; set; }

    internal InnerComputeEnvironmentInstanceLaunchTemplateFactory InstanceLaunchTemplateFactory { get; set; }

    protected override Humidifier.Batch.ComputeEnvironmentTypes.ManagedInstancesProvider Create()
    {
        var managedInstancesProviderResult = CreateManagedInstancesProvider();
        factoryAction?.Invoke(managedInstancesProviderResult);

        return managedInstancesProviderResult;
    }

    private Humidifier.Batch.ComputeEnvironmentTypes.ManagedInstancesProvider CreateManagedInstancesProvider()
    {
        var managedInstancesProviderResult = new Humidifier.Batch.ComputeEnvironmentTypes.ManagedInstancesProvider();

        return managedInstancesProviderResult;
    }
    public override void CreateChildren(Humidifier.Batch.ComputeEnvironmentTypes.ManagedInstancesProvider result)
    {
        base.CreateChildren(result);

        result.InfrastructureOptimization ??= InfrastructureOptimizationFactory?.Build();
        result.InstanceLaunchTemplate ??= InstanceLaunchTemplateFactory?.Build();
    }

} // End Of Class

